const sendTransaction = async (amountInUsd, selectedCurrency) => {
  if (!provider) {
    alert("Le provider n'est pas défini, veuillez connecter votre wallet.");
    return;
  }

  try {
    const signer = provider.getSigner();

    let amountToSend;

    // Si l'utilisateur choisit de payer en USD (nous allons ignorer ce cas et nous concentrer sur BNB)
    if (selectedCurrency === 'BNB') {
      // Conversion du montant en USD vers BNB
      const bnbToUsdRate = await getBnbToUsdRate(); // Obtenez le taux de conversion actuel
      if (bnbToUsdRate <= 0) {
        alert("Erreur de récupération du taux de conversion BNB/USD.");
        return;
      }

      // Calcul du montant en BNB
      const amountInBnb = amountInUsd / bnbToUsdRate; // Convertir l'USD en BNB
      amountToSend = ethers.utils.parseUnits(amountInBnb.toString(), 18); // Conversion en wei (unité la plus petite de BNB)
    }

    console.log("Montant à envoyer en BNB:", amountToSend);

    // Préparer la transaction
    const tx = {
      to: contractAddress,  // Adresse du contrat à payer
      value: amountToSend,  // Montant en BNB
      gasLimit: 50000,      // Limite de gaz
    };

    // Effectuer la transaction
    const transactionResponse = await signer.sendTransaction(tx);
    console.log("Transaction envoyée:", transactionResponse.hash);

    // Attendre la confirmation de la transaction
    const receipt = await transactionResponse.wait();
    if (receipt.status === 1) {
      console.log("Transaction réussie !");
      alert("Paiement effectué avec succès.");
      window.location.href = '/Delivrance_IndicateurD.html';  // Rediriger après paiement réussi
    } else {
      alert("Échec de la transaction.");
    }
  } catch (error) {
    console.error("Erreur lors de l'envoi de la transaction:", error.message);
    alert("Une erreur s'est produite lors de l'envoi de la transaction.");
  } finally {
    console.log("Transaction terminée.");
  }
};









